const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format((v||0)/100),exact=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:2}).format((v||0)/100);
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l1 14H4L5 7z M9 7V5a3 3 0 0 1 6 0v2',box:'m3 7 9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10 M7 4l10 6',tool:'m14 6 4 4 3-3a7 7 0 0 1-9 9l-7 6-3-3 7-7a7 7 0 0 1 9-9z',swap:'M3 7h17l-4-4 M21 17H4l4 4 M20 7l-4 4 M4 17l4-4',cart:'M2 3h3l3 12h11l3-9H6 M9 21h.01 M18 21h.01',wallet:'M21 8H5a3 3 0 0 1 0-6h13v6 M3 5v14a2 2 0 0 0 2 2h16V8 M16 12h5v5h-5z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-4 M16 3a4 4 0 0 1 0 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'m21 21-6-6 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',check:'m5 12 4 4L19 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',receipt:'M5 2h14v20l-3-2-4 2-4-2-3 2z M8 7h8 M8 11h8 M8 15h5',download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',phone:'M7 2h10v20H7z M10 18h4',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8C1 8 6-3 12 8c6-11 11 0 0 0',barcode:'M3 4v16 M6 4v16 M10 4v16 M12 4v16 M16 4v16 M19 4v16 M21 4v16',logout:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',trend:'m3 17 6-6 4 4 8-12 M15 3h6v6',close:'m6 6 12 12 M6 18 18 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
let state,page=location.hash.slice(1)||'overview',query='',filter='All',cart=[],draft={},formAction='',pendingKey='',busy=false;
const nav=[['WORKSPACE',[['overview','Overview','grid'],['sales','Sales & billing','bag'],['inventory','Inventory','box'],['service','Service desk','tool'],['exchange','Mobile exchange','swap']]],['OPERATIONS',[['purchase','Purchases','cart'],['returns','Returns','receipt'],['transfer','Stock transfers','swap']]],['BUSINESS',[['finance','Finance','wallet'],['expenses','Expenses','receipt'],['advances','Advances','wallet'],['closing','Daily closing','clock'],['attendance','Team & attendance','users'],['payroll','Salary & incentives','users'],['promotions','Discounts & gifts','gift'],['barcodes','Barcode studio','barcode'],['settings','Admin & settings','settings']]]];
const allowed={cashier:['overview','sales','inventory','service','advances','attendance','barcodes'],technician:['service'],accountant:['overview','inventory','purchase','returns','finance','expenses','advances','closing','payroll','barcodes']};
const canPage=p=>nav.flatMap(n=>n[1]).some(n=>n[0]===p)&&(state?.user.role==='owner'||allowed[state?.user.role]?.includes(p));
const docs=kind=>state.documents.filter(d=>d.kind===kind),match=d=>JSON.stringify(d).toLowerCase().includes(query.toLowerCase());
const badge=s=>`<span class="badge ${['Completed','Paid','Received','Available','Passed','Delivered','Present','Transferred','Issued'].includes(s)?'green':['Awaiting approval','Awaiting inspection','inspection','Open','Ready for pickup','Low stock'].includes(s)?'amber':'gray'}">${esc(s)}</span>`;
async function api(path,body,key){const res=await fetch(`/api/${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json',...(key?{'Idempotency-Key':key}:{})}:{},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok){if(res.status===401&&path==='state')return null;throw Error(data.error);}return data;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function refresh(){state=await api('state');if(!state)return login();if(!canPage(page))page=state.user.role==='technician'?'service':'overview';render();}
async function boot(){try{await refresh();}catch(e){$('#app').innerHTML=`<div class="loading"><div><h1>Unable to open workspace</h1><p>${esc(e.message)}</p><button class="primary" data-action="reload">Try again</button></div></div>`;}}
async function login(){const health=await api('health');$('#app').innerHTML=`<div class="login-shell"><div class="login-story"><div class="brand"><img src="/favicon.svg" alt="">mehers<span>WORKSPACE</span></div><div><span class="eyebrow">RETAIL, WITHOUT THE FRICTION</span><h1>Your shop.<br>Your people.<br>All together.</h1><p>One thoughtful workspace for every sale,<br>every handset, and every working day.</p></div><div class="byline">Crafted by <strong>newvora ↗</strong></div></div><div class="login-form"><span class="eyebrow">WELCOME TO MEHERS</span><h2>Let’s get to work.</h2><p class="muted">Sign in to your store workspace.</p><form id="login-form"><label>Username<input name="username" autocomplete="username" required placeholder="Your username"></label><label>Password<input name="password" type="password" autocomplete="current-password" required placeholder="Your password"></label><p id="form-error" class="error" role="alert"></p><button class="primary" type="submit">Sign in ${icon('arrow')}</button></form>${health.demo?'<div class="demo-login"><p>Take a look around with sample store data.</p><button class="secondary" data-action="demo">Explore demo workspace →</button></div>':''}<small>Mehers · Boudh, Odisha</small></div></div>`;}
const add=(label,action)=>`<button class="primary" data-form="${action}">${icon('plus')}${label}</button>`;
function heading(eyebrow,title,description,button=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${button}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">${icon('box')}<strong>No records yet</strong><span>Your next entry will appear here.</span></div></td></tr>`}</tbody></table></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,sub,i])=>`<section class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong><small>${sub}</small></section>`).join('')}</div>`;}
function toolbar(placeholder='Search records…',tabs=[]){return `<div class="table-toolbar"><div class="tabs">${tabs.map(t=>`<button class="${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="table-tools"><label class="search-input">${icon('search')}<input id="table-search" placeholder="${placeholder}" value="${esc(query)}" aria-label="Search this table"></label><button class="secondary compact" data-action="export">${icon('download')}Export</button></div></div>`;}
const rows=records=>records.filter(match).map(d=>[`<button class="text-link" data-detail="${d.id}">${d.id}</button>`,`<strong>${esc(d.party)}</strong>`,esc(d.date),exact(d.amount),badge(d.status),`<button class="row-open" data-detail="${d.id}" aria-label="View ${d.id}">${icon('arrow')}</button>`]);
function render(){const active=docs('service').filter(d=>d.status!=='Delivered').length;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><img src="/favicon.svg" alt="">mehers<span>WORKSPACE</span></a><div class="store-switch"><span class="store-icon">M</span><div><strong>Boudh store</strong><small>Mehers · Main branch</small></div><span class="live-dot"></span></div><nav>${nav.map(([group,items])=>{const visible=items.filter(([p])=>canPage(p));return visible.length?`<div class="nav-label">${group}</div>${visible.map(([p,label,i])=>`<button class="nav-item ${page===p?'active':''}" data-page="${p}">${icon(i)}<span>${label}</span>${p==='service'?`<b class="nav-count">${active}</b>`:''}</button>`).join('')}`:'';}).join('')}</nav><div class="sidebar-foot"><div class="support-mark">N</div><div>Built for your business<small>Powered by <a href="https://newvora.in" target="_blank" rel="noopener">newvora ↗</a></small></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${nav.flatMap(n=>n[1]).find(n=>n[0]===page)?.[1]}</strong></div><div class="top-actions"><button class="global-search" data-action="search" aria-label="Search workspace">${icon('search')}<span>Search anything…</span><kbd>Ctrl K</kbd></button><button class="icon-button notification" data-action="notifications" aria-label="View attention items">${icon('bell')}<i></i></button><div class="top-divider"></div><button class="profile" data-action="profile" aria-label="Your account"><span class="avatar">${esc(state.user.name[0])}</span><span>${esc(state.user.name)}<small>${esc(state.user.role)}</small></span>${icon('down')}</button></div></header>${state.demo?'<div class="demo-strip"><span class="live-dot"></span> Demo workspace · Sample data, saved on this computer <span>Designed for Mehers by Newvora</span></div>':''}<main id="main">${content()}</main><footer><span>Mehers Workspace <span class="footer-dot">·</span> Boudh, Odisha</span><span>${icon('check')} All changes saved to this server</span></footer></div>`;bindSearch();}
function dateOffset(n){const d=new Date(`${state.date}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function chart(){const dates=Array.from({length:7},(_,i)=>dateOffset(i-6)),values=dates.map(date=>docs('sale').filter(d=>d.date===date).reduce((s,d)=>s+d.amount,0)),max=Math.max(...values,10000),points=values.map((v,i)=>`${65+i*91},${178-v/max*142}`);return `<div class="chart"><svg viewBox="0 0 650 220" role="img" aria-label="Daily gross sales: ${dates.map((d,i)=>`${d}: ${money(values[i])}`).join('; ')}"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#7aab91" stop-opacity=".25"/><stop offset="100%" stop-color="#7aab91" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="65" x2="615" y1="${36+i*47}" y2="${36+i*47}" stroke="#e9ede9" stroke-dasharray="3 5"/><text x="0" y="${40+i*47}">${money(max*(1-i/3))}</text>`).join('')}<path d="M65,178 L${points.join(' L')} L611,178Z" fill="url(#area)"/><polyline points="${points.join(' ')}" fill="none" stroke="#36745c" stroke-width="2.5"/>${values.map((v,i)=>`<circle cx="${65+i*91}" cy="${178-v/max*142}" r="4" fill="#fff" stroke="#36745c" stroke-width="2"><title>${dates[i]}: ${money(v)}</title></circle><text x="${65+i*91}" y="209" text-anchor="middle">${new Date(dates[i]+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'short'})}</text>`).join('')}</svg></div>`;}
function overview(){const sales=docs('sale').filter(d=>d.date===state.date),stock=state.units.filter(u=>u.status==='available'),jobs=docs('service').filter(d=>d.status!=='Delivered'),low=state.products.filter(p=>p.stock<=p.reorder);return heading('YOUR DAILY PULSE','A clear view of your day.',`Welcome back, ${esc(state.user.name.split(' ')[0])}. Here’s what’s happening at your store.`,`<span class="date-pill">${icon('clock')}${new Date(state.date+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span>${canPage('sales')?add('New sale','sale'):''}`)+stats([['Today’s sales',money(sales.reduce((s,d)=>s+d.amount,0)),`${sales.length} invoices created today`,'bag'],['Available stock',stock.length,`${state.products.length} products across your store`,'box'],['Active repairs',jobs.length,`${jobs.filter(j=>j.status==='Ready for pickup').length} ready for pickup`,'tool'],['Team present',`${state.attendance.length}<span class="stat-denominator"> / ${state.employees.length}</span>`,'Checked in for today','users']])+`<div class="dashboard-grid"><section class="panel sales-panel"><div class="panel-heading"><div><h2>Sales at a glance</h2><p>Your store’s performance over the last 7 days</p></div><span class="subtle-pill">Last 7 days</span></div><div class="chart-summary"><strong>${money(docs('sale').filter(d=>d.date>=dateOffset(-6)).reduce((s,d)=>s+d.amount,0))}</strong><span><i class="legend-dot"></i>Gross billed sales</span></div>${chart()}</section><section class="panel attention"><div class="panel-heading"><h2>Needs your attention</h2><span class="count-pill">${low.length+jobs.length}</span></div>${[['inventory','box','amber',`${low.length} products running low`,'Keep your bestsellers in stock'],['service','tool','blue',`${jobs.length} repairs in progress`,'A little follow-up goes a long way'],['closing','wallet','sage',state.closings.some(c=>c.date===state.date)?'Today’s register is closed':'Daily closing is pending','Reconcile your cash before you leave']].map(([p,i,c,t,s])=>`<button class="attention-item" data-page="${p}"><span class="attention-icon ${c}-bg">${icon(i)}</span><span><strong>${t}</strong><small>${s}</small></span>${icon('chevron')}</button>`).join('')}<div class="insight"><span>THE SMALL THINGS ADD UP</span><p>A quick stock check today.<br>A smoother sales day tomorrow.</p><div class="insight-line"></div></div></section></div><div class="quick-actions"><span>Make it happen</span>${[['sale','New sale','bag','sales'],['purchase','Receive stock','box','purchase'],['service','Service intake','tool','service'],['expense','Add expense','wallet','expenses']].filter(a=>canPage(a[3])).map(([a,t,i])=>`<button data-form="${a}">${icon(i)}${t}${icon('plus')}</button>`).join('')}</div><div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Recent transactions</h2><p>The latest from your counter</p></div><button class="text-link" data-page="sales">View all ${icon('arrow')}</button></div>${table(['INVOICE / CUSTOMER','AMOUNT','PAYMENT','STATUS'],docs('sale').slice(0,5).map(d=>[`<button class="transaction-person" data-detail="${d.id}"><span class="initials">${esc(d.party.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span><strong>${esc(d.party)}</strong><small>${d.id}</small></span></button>`,`<strong>${money(d.amount)}</strong>`,esc([...d.data.payments.map(p=>p.method),...(d.data.creditAmount?['Credit']:[])].join(' + ')),badge(d.status)]))}</section><section class="panel stock-watch"><div class="panel-heading"><div><h2>Stock watch</h2><p>A timely nudge to reorder</p></div>${icon('box')}</div>${low.slice(0,4).map(p=>`<button class="stock-item" data-page="inventory"><span class="product-thumb">${icon(p.category==='Accessories'?'box':'phone')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.brand)}</small></span><b>${p.stock}<small>left</small></b></button>`).join('')||'<div class="empty">Stock levels look healthy.</div>'}<button class="stock-footer" data-page="inventory">Open inventory ${icon('arrow')}</button></section></div>`;}
function balance(account,credit=false){const l=state.ledger.find(l=>l.account===account);return l?(credit?l.credit-l.debit:l.debit-l.credit):0;}
function content(){
 if(page==='overview')return overview();
 if(page==='sales')return heading('THE SALES COUNTER','Good sales start here.','Create bills, find past invoices, and keep every payment connected.',add('New sale','sale'))+stats([['Gross sales',money(docs('sale').reduce((s,d)=>s+d.amount,0)),'All recorded invoices','bag'],['Invoices',docs('sale').length,'Search by customer or invoice','receipt'],['Returns',money(docs('return').filter(d=>d.data.type==='sales').reduce((s,d)=>s+d.amount,0)),'Linked to original sales','swap'],['Payment methods','5','Cash · UPI · Card · Bank · Finance','wallet']])+`<section class="panel">${toolbar('Customer, invoice, IMEI…')}${table(['INVOICE','CUSTOMER','DATE','TOTAL','STATUS',''],rows(docs('sale')))}</section>`;
 if(page==='inventory')return heading('EVERY HANDSET, ACCOUNTED FOR','Inventory','Model-level overview. IMEI-level control. One reliable stock ledger.',state.user.role==='owner'?add('Add product','product'):'')+stats([['Available units',state.units.filter(u=>u.status==='available').length,'Across shop floor and store room','box'],['Stock value',state.user.role==='cashier'?'Restricted':money(state.units.filter(u=>['available','inspection'].includes(u.status)).reduce((s,u)=>s+u.cost,0)),'At recorded purchase cost','wallet'],['Low-stock products',state.products.filter(p=>p.stock<=p.reorder).length,'At or below reorder level','trend'],['Awaiting inspection',state.units.filter(u=>u.status==='inspection').length,'Used devices and customer returns','search']])+`<section class="panel">${toolbar('Product, SKU, brand…',['All','Smartphones','Accessories','Used phones'])}${table(['PRODUCT','SKU','SELLING PRICE','AVAILABLE','STOCK HEALTH',''],state.products.filter(p=>(filter==='All'||p.category===filter)&&match(p)).map(p=>[`<div class="product-cell"><span class="product-thumb">${icon(p.category==='Accessories'?'box':'phone')}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.brand)} · ${esc(p.category)}</small></span></div>`,`<span class="mono">${esc(p.sku)}</span>`,money(p.price),`<strong>${p.stock}</strong> units`,badge(p.stock<=p.reorder?'Low stock':'Available'),`<button class="text-link" data-units="${p.id}">View units ${icon('arrow')}</button>${state.user.role==='owner'?` <button class="text-link" data-edit-product="${p.id}">Edit</button>`:''}`]))}</section>`;
 if(page==='service')return servicePage();
 if(page==='finance')return heading('MONEY, WITH CONTEXT','Finance','A balanced journal behind every posted transaction. Amounts in INR.',add('Lender settlement','lender-settlement')+(state.user.role==='owner'?add('Add owner funds','funding'):''))+stats([['Cash book balance',money(state.cash),'Running ledger balance','wallet'],['Customer advances',money(balance('Customer advances',true)),'Unsettled customer deposits','users'],['Finance receivable',money(balance('Finance receivable')),'Awaiting lender settlement','receipt'],['Journal balance',money(state.ledger.reduce((s,l)=>s+l.debit-l.credit,0)),'Debits less credits; should be zero','check']])+`<section class="panel"><div class="panel-heading"><div><h2>Trial balance</h2><p>Operational ledger · Not a statutory financial statement</p></div><button class="secondary" data-action="export">${icon('download')}Export</button></div>${table(['ACCOUNT','DEBITS','CREDITS','NET BALANCE'],state.ledger.map(l=>[esc(l.account),exact(l.debit),exact(l.credit),exact(l.debit-l.credit)]))}</section><div class="notice">Payment methods record how money was received or paid. Bank, UPI, card, and lender confirmations are recorded manually.</div>`;
 if(page==='attendance')return heading('YOUR PEOPLE','Team & attendance','A simple check-in and check-out for each working day.',state.user.role==='owner'?add('Add employee','employee'):'')+`<div class="team-grid">${state.employees.map(e=>{const a=state.attendance.find(a=>a.employee_id===e.id);return `<section class="panel employee-card"><span class="avatar large">${esc(e.name.split(' ').map(n=>n[0]).join(''))}</span><h2>${esc(e.name)}</h2><p>${esc(e.role)}</p>${badge(a?a.check_out?'Checked out':'Present':'Not checked in')}<div class="employee-times"><span>IN<strong>${a?.check_in||'—'}</strong></span><span>OUT<strong>${a?.check_out||'—'}</strong></span></div><button class="${a?'secondary':'primary'}" data-attendance="${e.id}" ${a?.check_out?'disabled':''}>${a?a.check_out?'Done for today':'Check out':'Check in'}</button></section>`;}).join('')||'<div class="empty">Add your first employee to begin.</div>'}</div>`;
 if(page==='closing')return closingPage();if(page==='barcodes')return barcodePage();if(page==='settings')return settingsPage();
 if(page==='promotions')return heading('THOUGHTFUL EXTRAS','Discounts & gifts','Apply discounts at checkout. Link every complimentary accessory to its sale.',add('Issue a gift','gift'))+stats([['Discounts given',money(docs('sale').reduce((s,d)=>s+d.data.items.reduce((a,i)=>a+i.discount,0),0)),'Captured on each invoice line','receipt'],['Cashier discount limit','5%','Higher discounts require the owner','check'],['Gifts issued',docs('gift').length,'Stock and promotional cost linked','gift'],['Gift policy','Accessories','Each gift references an existing sale','box']])+`<section class="panel"><div class="panel-heading"><h2>Gift register</h2></div>${table(['REFERENCE','CUSTOMER','DATE','VALUE','STATUS',''],rows(docs('gift')))}</section>`;
 const config={purchase:['BUYING & RECEIVING','Purchases','Receive each handset with its IMEI and landed cost.','Receive stock','purchase'],exchange:['A SECOND LIFE','Mobile exchange','Receive a device, inspect it, and apply its credit to a new purchase.','Receive exchange','exchange'],returns:['KEEP THE HISTORY','Sales & purchase returns','Reference the original transaction. Reverse stock and money together.','Create return','return'],transfer:['IN THE RIGHT PLACE','Stock transfers','Move available units between the shop floor and store room.','Transfer stock','transfer'],expenses:['EVERY RUPEE COUNTS','Expenses','Record day-to-day spending against the right payment account.','Add expense','expense'],advances:['CLEAR COMMITMENTS','Advances','Customer deposits and staff advances, with outstanding balances.','Record advance','advance'],payroll:['RECOGNISE THE WORK','Salary & incentives','Monthly salary payments, approved incentives, and advance recovery.','Pay salary','salary']}[page];
 if(config){const [eyebrow,title,desc,label,kind]=config;return heading(eyebrow,title,desc,add(label,kind))+`<section class="panel">${toolbar()}${table(['REFERENCE',page==='payroll'?'EMPLOYEE':'PARTY','DATE','AMOUNT','STATUS',''],rows(docs(kind)))}</section>${page==='exchange'?'<div class="notice">An exchange creates a credit liability and an inspection hold. Apply the credit to that customer’s sale or record a cash payout. Inspection release and credit redemption are tracked separately.</div>':''}${page==='payroll'?'<div class="notice">Incentives and other deductions are entered after owner approval. Statutory payroll calculations and attendance proration are not configured.</div>':''}`;}return '';
}
function servicePage(){const stages=['Received','Diagnosing','Awaiting approval','Repairing','Ready for pickup','Delivered'];return heading('CARE BEYOND THE SALE','Service desk','From first diagnosis to a happy handover. Every repair has a place.',add('New service job','service'))+`<div class="service-toolbar">${['All',...stages].map(s=>`<button data-filter="${s}" class="${filter===s?'selected':''}">${s}<span>${docs('service').filter(d=>s==='All'||d.status===s).length}</span></button>`).join('')}</div><div class="service-grid">${docs('service').filter(d=>filter==='All'||d.status===filter).map(d=>`<article class="panel job-card"><div class="job-top"><span class="mono">${d.id}</span>${badge(d.status)}</div><h2>${esc(d.data.device)}</h2><p>${esc(d.data.issue)}</p><div class="job-customer">${icon('users')}<span>${esc(d.party)}<small>${esc(d.data.phone||'Phone not recorded')}</small></span></div><dl><div><dt>Estimate</dt><dd>${money(d.amount)}</dd></div><div><dt>Assigned to</dt><dd>${esc(d.data.technician||'Unassigned')}</dd></div></dl><button class="secondary" data-detail="${d.id}">Open job card ${icon('arrow')}</button></article>`).join('')||'<div class="empty">No service jobs in this stage.</div>'}</div>`;}
function closingPage(){const closed=state.closings.find(c=>c.date===state.date),sales=docs('sale').filter(d=>d.date===state.date);return heading('FINISH WITH CONFIDENCE','Daily closing','Count the cash. Explain any difference. Close the day with a clear record.')+`<div class="closing-grid"><section class="panel closing-card"><span class="eyebrow">${state.date} · MAIN STORE</span><h2>${closed?'Your day is closed.':'Let’s balance the day.'}</h2><div class="closing-amount"><span>Expected cash in drawer</span><strong>${money(state.cash)}</strong></div><p class="muted">Running cash balance includes sales, refunds, expenses, owner funds, and advance movements.</p>${closed?badge('Completed'):`<button class="primary" data-form="closing">${icon('check')}Count & close register</button>`}</section><section class="panel"><div class="panel-heading"><h2>Closing history</h2></div>${table(['DATE','EXPECTED','COUNTED','DIFFERENCE'],state.closings.map(c=>[esc(c.date),money(c.expected),money(c.counted),`<span class="${c.difference?'error':''}">${money(c.difference)}</span>`]))}<div class="panel-heading"><h2>Today’s sales receipts</h2></div>${table(['METHOD','RECEIVED'],['Cash','UPI','Card','Bank transfer','Finance'].map(m=>[m,money(sales.reduce((s,d)=>s+d.data.payments.filter(p=>p.method===m).reduce((a,p)=>a+p.amount,0),0))]))}</section></div><div class="notice">Closing locks today’s financial entries. Discrepancies remain visible for review and are not silently written off. Sales receipts above exclude refunds and other cash movements; the expected drawer balance includes them.</div>`;}
function settingsPage(){return heading('MAKE IT YOURS','Admin & settings','Store identity, team access, and a record of every important action.')+`<div class="settings-grid"><section class="panel settings-card"><h2>Store profile</h2><div class="brand settings-brand"><img src="/favicon.svg" alt="">${esc(state.settings.name)}</div><p>${esc(state.settings.address)}</p><p>${esc(state.settings.phone)}</p><p class="muted">GSTIN: ${esc(state.settings.gstin||'Not configured')}</p><button class="secondary" data-form="settings">Edit store profile</button></section><section class="panel settings-card"><div class="panel-heading"><h2>Workspace access</h2>${add('Add user','user')}</div>${table(['USER','USERNAME','ROLE','ACCESS'],state.users.map(u=>[esc(u.name),esc(u.username),badge(u.role),u.id===state.user.id?'Current user':`<button class="text-link" data-access="${u.id}" data-active="${u.active?0:1}">${u.active?'Disable':'Enable'}</button>`]))}<p class="muted">Permissions are checked on the server. Disabling a user ends their sessions.</p></section></div><section class="panel"><div class="panel-heading"><h2>Audit trail</h2><span class="muted">Latest 100 events</span></div>${table(['WHEN','PERSON','ACTION','REFERENCE'],state.audit.map(a=>[esc(a.created_at)+' UTC',esc(a.name||a.actor),esc(a.action),esc(a.document_id)]))}</section>`;}
const code39={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','*':'nwnnwnwnn','$':'nwnwnwnnn','/':'nwnwnnnwn','+':'nwnnnwnwn','%':'nnnwnwnwn'};
function barcode(value){if(!/^[A-Z0-9 .$/+%\-]+$/.test(value))return '<small>Unsupported Code 39 characters in SKU</small>';let x=12,bars='';for(const c of `*${value}*`){[...code39[c]].forEach((w,i)=>{const width=w==='w'?3:1;if(i%2===0)bars+=`<rect x="${x}" y="0" width="${width}" height="40"/>`;x+=width;});x++;}return `<svg class="barcode" viewBox="0 0 ${x+12} 40" role="img" aria-label="Barcode for ${esc(value)}">${bars}</svg>`;}
function barcodePage(){return heading('SCAN. FIND. SELL.','Barcode studio','Print Code 39 labels. Scan a product SKU or a handset IMEI at the counter.',`<button class="primary" data-action="print-barcodes">${icon('barcode')}Print labels</button>`)+`<section class="panel settings-card"><label class="search-input">${icon('search')}<input id="barcode-search" placeholder="Filter by product or SKU" value="${esc(query)}"></label><div class="barcode-grid">${state.products.filter(match).map(p=>`<div class="barcode-label"><strong>${esc(p.name)}</strong>${barcode(p.sku)}<span>${esc(p.sku)}</span><b>${money(p.price)}</b></div>`).join('')}</div></section>`;}
const options=values=>values.map(v=>Array.isArray(v)?`<option value="${esc(v[0])}">${esc(v[1])}</option>`:`<option>${esc(v)}</option>`).join('');
const field=(name,label,type='text',value='',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} ${name==='imei'?'pattern="[0-9]{15}" maxlength="15" inputmode="numeric"':''} ${name==='password'?'minlength="12" autocomplete="new-password"':''}></label>`;
const select=(name,label,values,required=true)=>`<label>${label}<select name="${name}" ${required?'required':''}>${options(values)}</select></label>`;
const payment=()=>select('method','Payment method',['Cash','UPI','Card','Bank transfer']);
const product=()=>select('productId','Product model',state.products.map(p=>[p.id,p.name]));
const units=(list=state.units.filter(u=>u.status==='available'))=>select('unitId','Stock unit / IMEI',list.map(u=>[u.id,`${u.name} · ${u.imei||u.id} · ${u.location}`]));
function modalHead(eyebrow,title){return `<div class="modal-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
function modal(html,wide=false){$('#modal').innerHTML=`<div class="modal-inner ${wide?'wide':''}">${html}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function openForm(action,extra={}){
 formAction=action;pendingKey=crypto.randomUUID();if(action==='sale'){cart=[];draft={};return renderPOS();}
 const fields={
 purchase:()=>product()+field('party','Supplier')+field('imei','IMEI (required for phones)','text','',false)+field('cost','Landed cost (₹)','number')+select('location','Receive into',['Main store','Store room'])+payment(),
 exchange:()=>product()+field('party','Customer name')+field('phone','Customer phone','tel','',false)+field('imei','Incoming IMEI')+field('cost','Agreed exchange value (₹)','number')+select('condition','Condition',['Grade A','Grade B','Grade C'])+field('notes','Condition & ownership notes')+'<div class="form-note full">The device goes to inspection. Its value becomes a customer credit that can be applied at checkout.</div>',
 product:()=>field('name','Product name')+field('brand','Brand')+select('category','Category',['Smartphones','Accessories','Used phones'])+field('sku','SKU (uppercase letters, digits, hyphens)')+field('price','Selling price incl. tax (₹)','number')+field('cost','Default landed cost (₹)','number')+field('tax','Sales tax rate (%)','number','18')+field('reorder','Reorder level','number','3'),
 return:()=>select('originalId','Original invoice or purchase',state.documents.filter(d=>['sale','purchase'].includes(d.kind)).map(d=>[d.id,`${d.id} · ${d.party}`]))+units(state.units.filter(u=>['available','sold'].includes(u.status)))+field('reason','Reason for return')+payment()+'<div class="form-note full">This exact unit must belong to the original document. Customer returns go to inspection before resale.</div>',
 transfer:()=>units()+select('destination','Transfer to',['Store room','Main store']),
 expense:()=>field('party','Paid to')+select('category','Expense category',['Rent','Utilities','Travel','Repairs','Supplies','Marketing','Other'])+field('amount','Amount (₹)','number')+payment()+field('notes','Notes','text','',false),
 advance:()=>select('type','Advance type',['Customer','Staff'])+field('party','Customer / employee name')+field('amount','Amount (₹)','number')+payment()+field('notes','Purpose / reference'),
 service:()=>field('customer','Customer name')+field('phone','Phone number','tel')+field('device','Device model')+field('imei','IMEI')+field('issue','Reported issue')+field('estimate','Estimated charge (₹)','number','0')+select('technician','Assign technician',['Unassigned',...state.employees.filter(e=>e.role==='Technician').map(e=>e.name)])+field('accessories','Accessories received','text','',false)+field('condition','Visible damage / intake notes')+'<div class="form-note full">Do not store a customer’s device password or PIN.</div>',
 salary:()=>select('employeeId','Employee',state.employees.map(e=>[e.id,e.name]))+field('month','Payroll month','month',state.date.slice(0,7))+field('incentive','Approved incentive (₹)','number','0')+field('deduction','Other deductions (₹)','number','0')+select('advanceId','Staff advance to recover',[['','No recovery'],...docs('advance').filter(d=>d.data.type==='Staff'&&d.status==='Open').map(d=>[d.id,`${d.party} · ${money(d.data.remaining??d.amount)}`])],false)+field('advanceRecovery','Advance recovery (₹)','number','0')+payment()+field('notes','Payment notes','text','',false),
 closing:()=>`<div class="form-note full">Expected cash: <strong>${exact(state.cash)}</strong>. Closing locks today’s financial entries.</div>`+field('counted','Cash counted (₹)','number')+field('notes','Reason for difference, if any','text','',false),
 gift:()=>select('saleId','Linked sale',docs('sale').map(d=>[d.id,`${d.id} · ${d.party}`]))+units(state.units.filter(u=>u.status==='available'&&u.category==='Accessories')),
 settings:()=>field('name','Store name','text',state.settings.name)+field('address','Store address','text',state.settings.address)+field('phone','Store phone','text',state.settings.phone)+field('gstin','GSTIN','text',state.settings.gstin,false),
 user:()=>field('name','Full name')+field('username','Username')+select('role','Access role',['cashier','technician','accountant','owner'])+field('password','Initial password (12+ characters)','password'),
 employee:()=>field('name','Employee name')+select('role','Job role',['Store manager','Sales associate','Technician','Accountant'])+field('salary','Monthly base salary (₹)','number')+field('incentive','Reference incentive rate (%)','number','1'),
 funding:()=>field('amount','Capital introduced (₹)','number')+payment()+field('notes','Reference / purpose'),
 'lender-settlement':()=>select('saleId','Financed sale',docs('sale').filter(d=>d.data.payments.some(p=>p.method==='Finance')).map(d=>[d.id,`${d.id} · ${d.party}`]))+field('amount','Amount received (₹)','number')+select('method','Received into',['Bank transfer','UPI'])+field('reference','Lender settlement reference'),
 inspect:()=>`<input type="hidden" name="unitId" value="${esc(extra.unitId)}">`+field('notes','Inspection checklist & result')+'<div class="form-note">Confirm identity, ownership documentation, functionality, and condition before releasing to stock.</div>',
 settle:()=>`<input type="hidden" name="documentId" value="${esc(extra.id)}">`+field('amount','Cash settlement amount (₹)','number',extra.remaining/100)+payment(),
 'service-payment':()=>`<input type="hidden" name="id" value="${esc(extra.id)}">`+field('amount','Final repair charge (₹)','number',extra.amount/100)+payment()
 };
 const titles={purchase:'Receive stock',exchange:'Receive an exchange',product:'Add a product',return:'Create a linked return',transfer:'Transfer stock',expense:'Record an expense',advance:'Record an advance',service:'New service intake',salary:'Pay monthly salary',closing:'Count & close register',gift:'Issue a complimentary gift',settings:'Edit store profile',user:'Add workspace user',employee:'Add employee',funding:'Record owner capital','lender-settlement':'Record lender settlement',inspect:'Complete device inspection',settle:'Settle outstanding balance','service-payment':'Record repair payment'};
 if(!fields[action])return;
 modal(modalHead('MEHERS WORKSPACE',titles[action])+`<form id="operation-form"><div class="form-grid">${fields[action]()}</div><p id="form-error" class="error" role="alert"></p><div class="modal-footer"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">${icon('check')}${action==='closing'?'Confirm daily closing':'Save record'}</button></div></form>`);
}
function renderPOS(){const available=state.units.filter(u=>u.status==='available'&&u.location==='Main store'&&!cart.some(i=>i.unitId===u.id)),total=cart.reduce((s,i)=>s+i.price-i.discount,0);modal(modalHead('SALES COUNTER','A new sale, made simple.')+`<form id="sale-form"><div class="pos-layout"><div class="pos-products"><label class="search-input">${icon('search')}<input id="pos-search" placeholder="Scan IMEI / barcode or search product…" aria-label="Scan or search stock" autocomplete="off"></label><div class="pos-list">${state.products.filter(p=>available.some(u=>u.product_id===p.id)).map(p=>`<button type="button" class="pos-product" data-add-product="${p.id}" data-search="${esc((p.name+' '+p.sku+' '+available.filter(u=>u.product_id===p.id).map(u=>u.imei).join(' ')).toLowerCase())}"><span class="product-thumb">${icon(p.category==='Accessories'?'box':'phone')}</span><span><strong>${esc(p.name)}</strong><small>${available.filter(u=>u.product_id===p.id).length} available · ${esc(p.brand)}</small></span><b>${money(p.price)}</b>${icon('plus')}</button>`).join('')}</div></div><div class="pos-bill"><div class="form-grid">${field('customer','Customer name','text','Walk-in customer')}${field('phone','Phone (optional)','tel','',false)}</div><div class="cart-items">${cart.length?cart.map((i,n)=>`<div class="cart-item"><div><strong>${esc(i.name)}</strong><button type="button" class="remove-item" data-remove="${n}" aria-label="Remove ${esc(i.name)}">${icon('close')}</button></div><small>${esc(i.imei||i.unitId)}</small><div class="cart-price"><span>${money(i.price)}</span><label>Discount ₹ <input type="number" min="0" max="${i.price/100}" step=".01" data-discount="${n}" value="${i.discount/100}"></label></div></div>`).join(''):`<div class="empty">${icon('bag')}<strong>Your bill starts here</strong><span>Choose an item from available stock.</span></div>`}</div><div class="bill-total"><span>Total incl. configured tax</span><strong id="sale-total">${money(total)}</strong></div><div class="form-grid">${select('method','Primary payment',['Cash','UPI','Card','Bank transfer','Finance'])}${field('splitAmount','Second payment amount (₹)','number','0')}${select('splitMethod','Second payment method',['UPI','Cash','Card','Bank transfer','Finance'])}${select('employeeId','Salesperson',[['','Unassigned'],...state.employees.map(e=>[e.id,e.name])],false)}${select('creditId','Customer deposit / exchange credit',[['','No credit'],...state.documents.filter(d=>(d.kind==='exchange'||d.kind==='advance'&&d.data.type==='Customer')&&d.status!=='Settled').map(d=>[d.id,`${d.party} · ${money(d.data.remaining??d.amount)}`])],false)}${field('creditAmount','Credit to apply (₹)','number','0')}</div><p id="form-error" class="error" role="alert"></p><button type="submit" class="primary complete-sale" ${!cart.length?'disabled':''}>Complete sale ${icon('arrow')}</button><small class="bill-caption">Stock and payment are posted together.</small></div></div></form>`,true);for(const [name,value] of Object.entries(draft)){if($('#sale-form').elements[name])$('#sale-form').elements[name].value=value;}}
function saveDraft(){if($('#sale-form'))draft=Object.fromEntries(new FormData($('#sale-form')));}
function showUnits(productId){const p=state.products.find(p=>p.id===productId);modal(modalHead('STOCK TRACEABILITY',esc(p.name))+table(['IMEI / UNIT','CONDITION','LOCATION','STATUS',''],state.units.filter(u=>u.product_id===productId).map(u=>[`<span class="mono">${esc(u.imei||u.id)}</span>`,esc(u.condition),esc(u.location),badge(u.status),u.status==='inspection'&&state.user.role==='owner'?`<button class="text-link" data-inspect="${u.id}">Inspect & release</button>`:''])),true);}
function detail(id){const d=state.documents.find(d=>d.id===id);if(!d)return;const data=d.data;let html=modalHead(d.id,esc(d.kind==='service'?data.device:d.party))+`<div class="detail-meta"><span>${esc(d.date)}</span>${badge(d.status)}<strong>${exact(d.amount)}</strong></div>`;
 if(d.kind==='sale'){html+=`<div id="receipt"><div class="receipt-brand"><h2>${esc(state.settings.name)}</h2><p>${esc(state.settings.address)}</p><p>${esc(state.settings.phone)}</p><p>${state.settings.gstin?'GSTIN '+esc(state.settings.gstin):'Sales receipt · GSTIN not configured'}</p></div><h3>Sale ${esc(d.id)}</h3><p>${esc(d.party)} · ${esc(d.date)}</p>${table(['ITEM / IMEI','PRICE','DISCOUNT','NET'],data.items.map(i=>[`${esc(i.name)}<small class="block mono">${esc(i.imei||i.unitId)}</small>`,exact(i.price),exact(i.discount),exact(i.net)]))}<div class="receipt-total"><p>Included configured tax <strong>${exact(data.tax)}</strong></p><p>Total <strong>${exact(d.amount)}</strong></p>${data.creditAmount?`<p>Credit applied<strong>${exact(data.creditAmount)}</strong></p>`:''}${data.payments.map(p=>`<p>${esc(p.method)}<strong>${exact(p.amount)}</strong></p>`).join('')}</div><p class="muted">Thank you for shopping with Mehers.</p></div><button class="primary" data-action="print-receipt">${icon('receipt')}Print receipt</button>`;}
 else if(d.kind==='service'){const next={'Received':'Diagnosing','Diagnosing':'Awaiting approval','Awaiting approval':'Repairing','Repairing':'Ready for pickup','Ready for pickup':'Delivered'}[d.status];html+=`<dl class="detail-list">${[['Customer',d.party],['Phone',data.phone||'Not recorded'],['IMEI',data.imei],['Reported issue',data.issue],['Intake condition',data.condition||'Not recorded'],['Accessories',data.accessories||'None recorded'],['Technician',data.technician||'Unassigned'],['Payment',data.paid?exact(data.paidAmount)+' received':'Not paid']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="modal-footer">${d.status==='Ready for pickup'&&!data.paid&&state.user.role!=='technician'?`<button class="secondary" data-repair-payment="${d.id}">Record final payment</button>`:''}${next?`<button class="primary" data-stage="${d.id}" data-next="${next}">${next==='Repairing'?'Confirm customer approval & start repair':'Move to '+next} ${icon('arrow')}</button>`:''}</div>`;}
 else{html+=`<dl class="detail-list">${Object.entries(data).map(([k,v])=>`<div><dt>${esc(k.replace(/([A-Z])/g,' $1'))}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join('')}</dl>`;if(['advance','exchange'].includes(d.kind)&&d.status!=='Settled'&&['owner','accountant'].includes(state.user.role))html+=`<div class="notice">Remaining balance: ${money(data.remaining??d.amount)}</div><button class="primary" data-settle="${d.id}">Record cash settlement ${icon('arrow')}</button>`;}
 modal(html,true);
}
async function runAction(action,data,key=crypto.randomUUID()){if(busy)return;busy=true;const buttons=$('#modal').querySelectorAll('button[type="submit"]');buttons.forEach(b=>b.disabled=true);try{const result=await api(`actions/${action}`,data,key);$('#modal').close();await refresh();toast('Saved successfully');return result;}catch(e){if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}}
function exportCSV(){let data;if(page==='finance')data=state.ledger;else if(page==='inventory'||page==='barcodes')data=state.products.filter(p=>(filter==='All'||p.category===filter)&&match(p));else{const kind={sales:'sale',purchase:'purchase',exchange:'exchange',returns:'return',transfer:'transfer',expenses:'expense',advances:'advance',payroll:'salary'}[page];data=(kind?docs(kind):state.documents).filter(match).map(({data,...d})=>d);}if(!data.length)return toast('There are no records to export.');const keys=Object.keys(data[0]),safe=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"',blob=new Blob(['\uFEFF'+[keys,...data.map(r=>keys.map(k=>r[k]))].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`mehers-${page}-${state.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function showSearch(){modal(modalHead('FIND IT IN A MOMENT','Search your workspace')+`<label class="search-input search-large">${icon('search')}<input id="global-query" placeholder="Customer, invoice, IMEI, product…" autofocus></label><div id="global-results" class="global-results"><p class="muted">Search by name, invoice, SKU, or IMEI.</p></div>`);$('#global-query').focus();}
function searchResults(value){const q=value.toLowerCase().trim();if(!q){$('#global-results').innerHTML='<p class="muted">Type to search your workspace.</p>';return;}const records=state.documents.filter(d=>JSON.stringify(d).toLowerCase().includes(q)).slice(0,8),products=state.products.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(q)).slice(0,5),unitMatches=state.units.filter(u=>`${u.imei} ${u.id}`.toLowerCase().includes(q)).slice(0,8);$('#global-results').innerHTML=records.map(d=>`<button class="search-result" data-detail="${d.id}">${icon('receipt')}<span><strong>${esc(d.party)}</strong><small>${d.id} · ${esc(d.kind)}</small></span>${money(d.amount)}</button>`).join('')+[...products.map(p=>({name:p.name,product_id:p.id,id:p.sku})),...unitMatches].map(u=>`<button class="search-result" data-units="${u.product_id}">${icon('phone')}<span><strong>${esc(u.name)}</strong><small>${esc(u.imei||u.id)}</small></span>${icon('arrow')}</button>`).join('')||'<div class="empty">No matching records.</div>';}
function bindSearch(){const input=$('#table-search')||$('#barcode-search');if(input)input.addEventListener('input',e=>{const position=e.target.selectionStart;query=e.target.value;$('#main').innerHTML=content();bindSearch();const next=$('#table-search')||$('#barcode-search');next.focus();next.setSelectionRange(position,position);});}
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.page){if(!canPage(el.dataset.page))return toast('This area is restricted to the assigned role.');page=el.dataset.page;query='';filter='All';location.hash=page;render();window.scrollTo(0,0);return;}
 if(el.dataset.form)return openForm(el.dataset.form);
 if(el.dataset.filter){filter=el.dataset.filter;return render();}
 if(el.dataset.detail)return detail(el.dataset.detail);
 if(el.dataset.editProduct){const p=state.products.find(p=>p.id===el.dataset.editProduct);openForm('product');formAction='update-product';const f=$('#operation-form');f.insertAdjacentHTML('beforeend',`<input type="hidden" name="id" value="${p.id}">`);for(const [k,v] of Object.entries(p)){if(f.elements[k])f.elements[k].value=['price','cost','tax'].includes(k)?v/100:v;}return;}
 if(el.dataset.units)return showUnits(el.dataset.units);
 if(el.dataset.inspect)return openForm('inspect',{unitId:el.dataset.inspect});
 if(el.dataset.settle){const d=state.documents.find(d=>d.id===el.dataset.settle);return openForm('settle',{id:d.id,remaining:d.data.remaining??d.amount});}
 if(el.dataset.repairPayment){const d=state.documents.find(d=>d.id===el.dataset.repairPayment);return openForm('service-payment',{id:d.id,amount:d.amount});}
 if(el.dataset.access)return runAction('access',{userId:el.dataset.access,active:Number(el.dataset.active)});
 if(el.dataset.stage)return runAction('service',{id:el.dataset.stage,status:el.dataset.next});
 if(el.dataset.attendance)return runAction('attendance',{employeeId:el.dataset.attendance});
 if(el.dataset.addProduct){saveDraft();const u=state.units.find(u=>u.product_id===el.dataset.addProduct&&u.status==='available'&&u.location==='Main store'&&!cart.some(c=>c.unitId===u.id));if(u)cart.push({unitId:u.id,name:u.name,price:u.price,imei:u.imei,discount:0});return renderPOS();}
 if(el.dataset.remove!==undefined){saveDraft();cart.splice(Number(el.dataset.remove),1);return renderPOS();}
 const action=el.dataset.action;
 if(action==='close')return $('#modal').close();if(action==='reload')return boot();
 if(action==='demo'){try{await api('demo',{});await refresh();}catch(e){toast(e.message);}return;}
 if(action==='search')return showSearch();if(action==='menu')return $('.sidebar').classList.toggle('mobile-open');
 if(action==='notifications'){modal(modalHead('YOUR ATTENTION LIST','A few things to keep an eye on')+`<div class="notice">${state.products.filter(p=>p.stock<=p.reorder).length} products need replenishment. ${docs('service').filter(d=>d.status!=='Delivered').length} service jobs remain open.</div><button class="secondary" data-action="close">Got it</button>`);return;}
 if(action==='profile'){modal(modalHead('YOUR ACCOUNT',esc(state.user.name))+`<p>Signed in as ${esc(state.user.role)}.</p><button class="secondary" data-action="logout">${icon('logout')}Sign out</button>`);return;}
 if(action==='logout'){await api('logout',{});$('#modal').close();state=null;return login();}if(action==='export')return exportCSV();
 if(action==='print-receipt'||action==='print-barcodes'){document.body.classList.add(action);window.print();document.body.classList.remove(action);}
});
document.addEventListener('input',e=>{if(e.target.id==='global-query')searchResults(e.target.value);if(e.target.id==='pos-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.pos-product').forEach(p=>p.hidden=!p.dataset.search.includes(q));}if(e.target.dataset.discount!==undefined){cart[Number(e.target.dataset.discount)].discount=Math.round(Number(e.target.value)*100);$('#sale-total').textContent=money(cart.reduce((s,i)=>s+i.price-i.discount,0));}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state){e.preventDefault();showSearch();}if(e.key==='Enter'&&e.target.id==='pos-search'){e.preventDefault();const value=e.target.value.trim(),u=state.units.find(u=>u.imei===value&&u.status==='available'&&u.location==='Main store'&&!cart.some(c=>c.unitId===u.id));if(u){saveDraft();cart.push({unitId:u.id,name:u.name,price:u.price,imei:u.imei,discount:0});renderPOS();}else{const p=[...document.querySelectorAll('.pos-product')].find(p=>!p.hidden);if(p)p.click();}}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const data=Object.fromEntries(new FormData(e.target));
 if(e.target.id==='login-form'){try{await api('login',data);await refresh();}catch(err){$('#form-error').textContent=err.message;}return;}
 if(e.target.id==='operation-form'){for(const k of ['amount','cost','price','estimate','incentive','deduction','counted','salary','advanceRecovery'])if(k in data)data[k]=Math.round(Number(data[k])*100);if('tax' in data)data.tax=Math.round(Number(data.tax)*100);if('reorder'in data)data.reorder=Number(data.reorder);await runAction(formAction,data,pendingKey);return;}
 if(e.target.id==='sale-form'){const total=cart.reduce((s,i)=>s+i.price-i.discount,0),split=Math.round(Number(data.splitAmount||0)*100),creditAmount=Math.round(Number(data.creditAmount||0)*100);if(split<0||creditAmount<0||split+creditAmount>total)return $('#form-error').textContent='Credit and second payment cannot exceed the bill total.';const payments=total-creditAmount-split>0?[{method:data.method,amount:total-creditAmount-split}]:[];if(split)payments.push({method:data.splitMethod,amount:split});const result=await runAction('sale',{customer:data.customer,phone:data.phone,employeeId:data.employeeId,creditId:data.creditId,creditAmount,items:cart.map(({unitId,discount})=>({unitId,discount})),payments},pendingKey);if(result){cart=[];draft={};detail(result.id);}}
});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(state&&canPage(p)){page=p;query='';filter='All';render();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});boot();
